-- RC-868, RC-869 (RP-123): variant experiments, behind FF_VARIANT_EXPERIMENTS. otel_spans keeps each
-- span's own ratel.variant.experiment, ratel.variant.name and the other ratel.variant.* descriptors
-- (keyed without the prefix); otel_trace_summaries keeps the trace's variant, rolled up by the summary
-- sweep from the root span, else the first tagged span. variant_attribute_mappings holds a project's
-- own span attribute read as a variant name of one experiment, at most 20 per project.
-- Generated by drizzle-kit from ingest/otlp/schema.ts, synthesis/traces/schema.ts and
-- ingest/variants/schema.ts, then written as upstream's 0110 and 0111 (ratel-cloud): IF NOT EXISTS,
-- with the foreign key inline, so a database migrated by ratel-cloud already has them and this is a
-- no-op there. The text columns are nullable with no default and the jsonb columns have a constant
-- default, so every ALTER changes the catalog only and rewrites no row; existing rows read null and
-- '{}'. The spans index is partial and builds empty. On a large otel_spans, build it first, outside a
-- transaction (psql autocommit), after the three otel_spans ALTER TABLE statements:
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "otel_spans_project_variant_started_idx" ON "otel_spans" USING btree ("project_id","variant_experiment","variant_name","started_at") WHERE "variant_experiment" is not null or "variant_name" is not null;
-- The CREATE INDEX IF NOT EXISTS below is then a no-op. Nothing to backfill: spans carry variant tags
-- only once the switch is on.
CREATE TABLE IF NOT EXISTS "variant_attribute_mappings" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,
	"attribute_key" text NOT NULL,
	"experiment" text NOT NULL,
	"created_by" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "variant_attribute_mappings_project_key_idx" ON "variant_attribute_mappings" USING btree ("project_id","attribute_key");--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "variant_experiment" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "variant_name" text;--> statement-breakpoint
ALTER TABLE "otel_spans" ADD COLUMN IF NOT EXISTS "variant_attrs" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "otel_trace_summaries" ADD COLUMN IF NOT EXISTS "variant_experiment" text;--> statement-breakpoint
ALTER TABLE "otel_trace_summaries" ADD COLUMN IF NOT EXISTS "variant_name" text;--> statement-breakpoint
ALTER TABLE "otel_trace_summaries" ADD COLUMN IF NOT EXISTS "variant_attrs" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "otel_spans_project_variant_started_idx" ON "otel_spans" USING btree ("project_id","variant_experiment","variant_name","started_at") WHERE "otel_spans"."variant_experiment" is not null or "otel_spans"."variant_name" is not null;
